import QueryString from 'qs';

import { Environment } from '@game-studio/utilities';

import { Locale } from '../types';

export type LaunchOrigin = 'arcade' | 'bingo' | 'international' | undefined;
export type QueryStringParams = {
    /** required - sent as skin */
    currentSkin: string;
    /** optional - sent by the apps as env */
    environment: Environment | undefined;
    /** default: 'arcade' - sent as shell */
    launchedFrom: LaunchOrigin;
    /** optional - sent by GiG */
    parentGame: string | undefined;
    /** determined by received parentGame value */
    isSubGame: boolean;
    /** sent by new shell. Default: 'en-gb' */
    locale: Locale;
    /** optional - sent by new shell */
    isUnAuthDemoMode: boolean;
    /** sent by new shell. Default: 'UK_TOM' */
    operator: string;

    // Some other values that are sent from various places but not currently used

    /** sent by new shell but unused by arcade (used by bingo) */
    // operator: string;

    /** sent by old shell, new shell and apps but unused */
    // sessionResumptionAuthId: string;
    /** sent by old shell, new shell and apps but unused */
    // userId: number;
    /** sent by old shell, new shell and apps but unused */
    // crossCheck: number;
    /** sent by old shell, new shell and apps but unused */
    // siteId: number;
    /** sent by old shell, new shell and apps but unused */
    // deviceId: string;

    /** sent by apps (as version) but unused */
    // appVersion: string | undefined;
    /** sent by apps but unused */
    // username: string;
    /** sent by apps but unused */
    // game: string;
    /** sent by apps but unused */
    // deviceType: string;
    /** sent by apps but unused */
    // host: string;
}

function readQueryStringParams(): QueryStringParams {
    const data = QueryString.parse(window.location.search, { ignoreQueryPrefix: true });

    if (data.skin === undefined) {
        throw new Error('Missing skin name as "skin" from the query string');
    } else if (typeof data.skin !== 'string') {
        throw new Error('Invalid data received for "skin" in the query string');
    }

    if (data.env !== undefined && (typeof data.env !== 'string' || data.env !== 'debug' && data.env !== 'dev' && data.env !== 'stage' && data.env !== 'live')) {
        throw new Error('Invalid data received for "env" in the query string');
    }

    if (data.parentGame !== undefined && (typeof data.parentGame !== 'string')) {
        throw new Error('Invalid data received for "parentGame" in query string');
    }

    if (data.shell !== undefined && (typeof data.shell !== 'string' || data.shell !== 'arcade' && data.shell !== 'bingo' && data.shell !== 'international')) {
        throw new Error('Invalid data received for "shell" in query string');
    }

    if (data.locale !== undefined && (typeof data.locale !== 'string')) {
        throw new Error('Invalid data received for "locale" in query string');
    }

    if (data.mode !== undefined && (typeof data.mode !== 'string')) {
        throw new Error('Invalid data received for "mode" in query string');
    }

    if (data.operator !== undefined && (typeof data.operator !== 'string')) {
        throw new Error('Invalid data received for "operator" in query string');
    }

    if (data.shell as LaunchOrigin === 'international') {
        data.shell = 'arcade';
    }

    return {
        currentSkin: data.skin,
        environment: data.env,
        launchedFrom: data.shell as LaunchOrigin || 'arcade',
        parentGame: data.parentGame,
        isSubGame: data.parentGame !== undefined ? true : false,
        locale: (data.locale as Locale) || 'en-gb',
        isUnAuthDemoMode: data.mode === 'demo' ? true : false,
        operator: data.operator ?? 'UK_TOM'
    };
}

export const queryStringParams = readQueryStringParams();